const test = require('node:test');
const assert = require('node:assert');
const { parsePort } = require('../port.js');
test('parses a port', () => { assert.strictEqual(parsePort('8080'), 8080); });
test('rejects a port above 65535', () => { assert.throws(() => parsePort('70000')); });
test('rejects junk', () => { assert.throws(() => parsePort('abc')); });
